"use strict";exports.id=729,exports.ids=[729],exports.modules={10729:(a,b,c)=>{c.d(b,{HI:()=>e,N7:()=>i,bG:()=>j,t4:()=>d,x8:()=>k,zX:()=>h});let d=[{slug:"pashmina-guide",name:"Pashmina Guide",description:"What Pashmina actually is, how to judge it, and how to buy it without being sold something else."},{slug:"kashmiri-craft",name:"Kashmiri Craft",description:"Sozni, kani, tilla and jamawar — the techniques and the people who keep them."},{slug:"indian-textiles",name:"Indian Textiles",description:"Handloom traditions from Kashmir to Varanasi, and how they travelled."},{slug:"fashion",name:"Fashion",description:"Wearing handwoven cloth in a modern wardrobe."},{slug:"care-guide",name:"Care Guide",description:"Storing, cleaning and repairing fine textiles so they outlive you."},{slug:"gift-guide",name:"Gift Guide",description:"Choosing a textile as a present — weddings, occasions and corporate gifting."},{slug:"style-guide",name:"Style Guide",description:"How to drape, knot and layer shawls, stoles and dupattas."},{slug:"craftsmanship",name:"Craftsmanship",description:"Inside the workshop: looms, dyes, certification and the people at the bench."}],e=new Map(d.map(a=>[a.slug,a])),f=(a,b)=>({url:`/images/blog/${a}.png`,alt:b,width:1200,height:750}),g=[{slug:"what-is-pashmina",title:"What Is Pashmina?",excerpt:"Pashmina is a fibre, not a style of shawl. Here is where it comes from, why it costs what it costs, and what the word has come to mean in shops that should know better.",category:"pashmina-guide",author:"Pashmore Editorial",publishedAt:"2026-01-14",updatedAt:"2026-05-02",readingMinutes:7,cover:f("what-is-pashmina","Undyed Pashmina fibre before spinning, photographed in daylight"),blocks:[{type:"paragraph",text:"Ask ten shops what Pashmina is and you will get ten answers, most of them wrong. It is not a weave, a pattern, a size of shawl or a region of manufacture. Pashmina is a fibre — specifically, the winter underfleece of the Changthangi goat."},{type:"heading",text:"Where it comes from"},{type:"paragraph",text:"Changthangi goats live on the Changthang plateau in Ladakh, at altitudes above 4,000 metres, where winter temperatures fall past −30\xb0C. To survive that, they grow a second coat beneath their outer hair: a dense, extremely fine down called pashm. When spring arrives and the animals begin to moult, herders comb the down out by hand. The goats are never shorn — shearing would cut the coarse outer hair into the fleece and ruin it."},{type:"paragraph",text:"A single goat yields roughly 150 grams of usable fibre a year. A full shawl needs the annual yield of three to four animals. That number, more than anything else, sets the price."},{type:"heading",text:"Why fineness matters"},{type:"paragraph",text:"Pashm measures between 12 and 15 microns in diameter. Fine merino wool sits around 19 microns; a human hair is closer to 70. Below about 16 microns, wool stops being felt as prickle by almost everyone, which is why Pashmina can be worn directly against the neck by people who find ordinary wool intolerable."},{type:"paragraph",text:"Fineness also explains the warmth-to-weight ratio. A 180-gram Pashmina shawl traps more still air per gram than a 400-gram wool one, so it is warmer than its weight suggests and far less bulky under a coat."},{type:"heading",text:"Why it has to be spun by hand"},{type:"paragraph",text:"Fibre this fine breaks under the tension of mill spinning. Traditional pashm is spun on a hand charkha, historically almost always by women working at home, at a rate of a few grams an hour. The resulting yarn varies slightly in thickness along its length — and that irregularity is what gives handwoven Pashmina its living surface. Machine-made imitations are perfectly uniform, which is precisely how you spot them."},{type:"heading",text:"What the word has come to mean"},{type:"paragraph",text:'In much of the market, "pashmina" now describes a size and drape of scarf rather than a material. A great deal of what is sold under the name is viscose, or wool with a token percentage of pashm blended in. Neither is illegal, and neither is necessarily bad cloth — but neither is Pashmina.'},{type:"list",items:["Genuine pure Pashmina is warm to the touch immediately; viscose feels cool and slippery.","The surface should be matte and faintly hazy, never glossy.","Look closely at the weave: hand-spun yarn is never perfectly even.","Ask for documentation. A real supplier can name the micron grade, the loom and the weaver."]},{type:"heading",text:"Kashmir’s part in it"},{type:"paragraph",text:"The fibre comes from Ladakh; the craft comes from Kashmir. For centuries, raw pashm has travelled to Srinagar to be sorted, dehaired, spun, woven, dyed and embroidered. The Kashmir Pashmina GI registration exists to protect exactly this — the combination of fibre and hand-processing, not the word alone."},{type:"quote",text:"Cloth this fine cannot be hurried. Every shortcut shows in the surface.",attribution:"Ghulam, master weaver, Srinagar"},{type:"collectionLink",slug:"pure-pashmina",label:"Browse the Pure Pashmina collection"}],faqs:[{question:"Is Pashmina the same as cashmere?",answer:"Pashmina is a type of cashmere — the finest grade, from Changthangi goats. All Pashmina is cashmere; most cashmere is not Pashmina. Commercial cashmere is typically 16–19 microns; pashm is 12–15."},{question:"Why is pure Pashmina so expensive?",answer:"One goat yields about 150 grams a year and a shawl needs three to four goats’ worth, plus hand-dehairing, hand-spinning and six weeks or more on a handloom. The cost is almost entirely raw fibre and skilled labour."},{question:"Does the wedding-ring test prove authenticity?",answer:"Partly. A fine, unembroidered shawl woven from sub-14-micron fibre will pass through a ring, but so will a thin viscose scarf, and a heavier embroidered Pashmina will not. Use it alongside touch, surface and documentation."}],relatedProductSlugs:["ivory-heritage-pashmina-shawl","warm-beige-ring-pashmina-shawl","handloom-pashmina-solid-shawl-mist"],relatedCollectionSlugs:["pure-pashmina","pashmina","womens-pashmina"]},{slug:"how-to-identify-quality-pashmina",title:"How to Identify a Quality Pashmina Shawl",excerpt:"Six checks you can make in thirty seconds, in any shop, without special equipment — and the two tests that are worth ignoring.",category:"pashmina-guide",author:"Pashmore Editorial",publishedAt:"2026-02-08",readingMinutes:6,cover:f("how-to-identify-quality-pashmina","A cream Pashmina shawl examined closely against natural light"),blocks:[{type:"paragraph",text:"Most buying advice about Pashmina is either mystical or useless. What follows is what an experienced buyer actually does when a shawl is put in front of them."},{type:"heading",text:"1. Feel it before you look at it"},{type:"paragraph",text:"Genuine pashm registers as warm within a second or two of touching your palm, because it is a poor conductor and immediately traps body heat. Viscose and polyester feel cool and slick. This is the single most reliable field test there is."},{type:"heading",text:"2. Hold it to the light"},{type:"paragraph",text:"Look at the weave against a window. Hand-spun yarn varies in thickness, so the grid of warp and weft should look slightly irregular — alive rather than printed. A perfectly even, glassy grid means machine yarn."},{type:"heading",text:"3. Check the surface for haze"},{type:"paragraph",text:"Pashm has a faint halo of fibre ends that gives it a matte, slightly foggy surface. Sheen is a warning sign: silk blends have some lustre by design, but a bright, uniform shine usually means viscose."},{type:"heading",text:"4. Look at the edges and fringe"},{type:"paragraph",text:'Hand-knotted fringe is uneven in a way that machine overlocking never is. A hand-rolled edge should show tiny irregular stitches on the reverse. Perfect machine hemming on an "artisan" piece is a contradiction worth asking about.'},{type:"heading",text:"5. Turn the embroidery over"},{type:"paragraph",text:"On real sozni work, the reverse is nearly as clean as the face — that is the whole point of the technique, and it is why it takes so long. Loose floats and knots on the back indicate a faster, cheaper stitch."},{type:"heading",text:"6. Ask four questions"},{type:"list",items:["What is the micron grade of the fibre?","Was it hand-spun on a charkha or mill-spun?","Which loom was it woven on, and by whom?","Is there a GI or craft certificate with it?"]},{type:"paragraph",text:"A serious supplier answers all four without hesitating. A reseller who has never seen the loom will change the subject."},{type:"heading",text:"Two tests worth ignoring"},{type:"paragraph",text:"The burn test — pulling a thread and lighting it — does distinguish protein fibre from plastic, but it destroys part of the piece and no reputable shop will let you do it. The ring test is charming and often quoted, but it only works on fine unembroidered shawls, and a cheap synthetic scarf passes it easily. Treat it as a demonstration of fineness, not proof of authenticity."},{type:"productLink",slug:"warm-beige-ring-pashmina-shawl",label:"See a ring-test certified shawl"}],faqs:[{question:"Can I tell quality from price alone?",answer:"Price sets a floor, not a ceiling. Genuine hand-spun, handwoven pure Pashmina below roughly ₹6,000 is implausible on raw material cost alone — but a high price is no guarantee of anything on its own."},{question:"What does a GI certificate actually certify?",answer:"The Kashmir Pashmina Geographical Indication mark certifies that the fibre is Changthangi pashm and that the hand-processing took place in Kashmir. It is issued after laboratory fibre testing."}],relatedProductSlugs:["warm-beige-ring-pashmina-shawl","kashmiri-sozni-embroidered-pashmina-shawl"],relatedCollectionSlugs:["pure-pashmina","kashmiri-collection"]},{slug:"how-to-care-for-pashmina",title:"How to Care for Your Pashmina",excerpt:"Handwoven Pashmina should outlive you. Storing it flat, airing it instead of washing it, and knowing when to call a specialist is most of the job.",category:"care-guide",author:"Pashmore Editorial",publishedAt:"2026-03-05",readingMinutes:5,cover:f("how-to-care-for-pashmina","A folded Pashmina shawl resting in a muslin storage sleeve"),blocks:[{type:"paragraph",text:"Fine cashmere is not fragile, but it is unforgiving of the wrong habits. Almost all the damage we see on pieces sent back for repair comes from three things: hangers, washing machines and plastic storage."},{type:"heading",text:"Air it, do not wash it"},{type:"paragraph",text:"Pashm is naturally antibacterial and does not hold odour the way cotton does. After wearing, hang the piece over a chair back in a ventilated room for a few hours and it will recover on its own. Most shawls need cleaning once a season at most."},{type:"heading",text:"When it does need cleaning"},{type:"list",items:["Embroidered, kani or zari pieces: dry clean only, with someone who handles fine cashmere.","Plain cashmere and merino: hand wash in cold water with a pH-neutral cashmere detergent.","Never wring. Press water out between two towels and dry flat, away from sun and radiators.","Spot-treat marks immediately with a damp cloth and no soap."]},{type:"heading",text:"Storage"},{type:"paragraph",text:"Fold, never hang. A hanger puts the entire weight of the cloth on two points and will distort the shoulders of a shawl within a season. Store folded in the muslin sleeve the piece arrived in, or any breathable cotton bag — plastic traps moisture and invites mildew."},{type:"paragraph",text:"Refold along a different line each year so a permanent crease never sets. Keep a cedar block or a few dried lavender sachets nearby; moths are attracted to protein fibre, and they go for the parts you cannot see."},{type:"heading",text:"Pilling and snags"},{type:"paragraph",text:"Some pilling in the first season is normal — it is short fibre working its way out, not a fault. Remove it with a cashmere comb, working in one direction, never a razor. If a thread pulls, do not cut it: ease it back through to the reverse with a blunt needle."},{type:"heading",text:"What ruins a shawl fastest"},{type:"list",items:["Perfume sprayed directly onto the cloth — alcohol marks dye permanently.","Jewellery with open settings, which snags a fine weave immediately.","Direct sunlight in storage, which fades natural dyes in months.","Ironing embroidery face-down onto a hard board, which flattens the relief for good."]},{type:"collectionLink",slug:"pure-pashmina",label:"Shop pure Pashmina"}],faqs:[{question:"Can I machine wash a Pashmina shawl?",answer:"No. Even a wool cycle agitates enough to felt fibre this fine. Hand wash plain cashmere in cold water, and dry clean anything embroidered or woven with metallic thread."},{question:"How do I get a crease out?",answer:"Hang the piece in a steamy bathroom for twenty minutes, or hold a steamer 20 cm away and let the steam fall through it. Do not press an iron onto embroidery."},{question:"How often should I dry clean?",answer:"Once a season at most. Dry cleaning solvents are hard on fine fibre; airing between wears does more good than cleaning does."}],relatedProductSlugs:["ivory-heritage-pashmina-shawl","sand-cashmere-stole"],relatedCollectionSlugs:["pure-pashmina","fine-wool"]},{slug:"pashmina-vs-wool",title:"The Difference Between Pashmina and Wool",excerpt:"They are both animal fibres, they both keep you warm, and they behave nothing alike. A practical comparison, by weight, warmth, price and use.",category:"pashmina-guide",author:"Pashmore Editorial",publishedAt:"2026-03-26",readingMinutes:6,cover:f("pashmina-vs-wool","Pashmina and handloom wool cloth laid side by side for comparison"),blocks:[{type:"paragraph",text:"Both come from animals, both trap air, both are sold as winter cloth. Beyond that they are genuinely different materials, and choosing between them is mostly a question of what you want the piece to do."},{type:"heading",text:"Diameter is the whole story"},{type:"paragraph",text:"Sheep’s wool used in shawls runs from 19 microns (fine merino) up past 28 (handloom wool). Pashm is 12–15. That single difference produces almost every other difference between the two."},{type:"heading",text:"Warmth and weight"},{type:"paragraph",text:"Per gram, Pashmina is substantially warmer, because finer fibre packs more insulating air per unit of mass. In absolute terms a heavy 450-gram handloom wool shawl will still out-warm a 180-gram Pashmina one — it simply weighs two and a half times as much and looks it."},{type:"heading",text:"Against the skin"},{type:"paragraph",text:"Below about 16 microns, wool stops triggering the prickle response. Pashmina and fine cashmere can be worn on bare skin by nearly everyone; ordinary wool cannot."},{type:"heading",text:"Durability"},{type:"paragraph",text:"Here wool wins. A Kashmiri handloom wool shawl will take daily abuse for decades and improve as it softens. Pashmina wants more care: it pills more readily in its first season, snags on jewellery, and does not enjoy being sat on."},{type:"heading",text:"Which to buy"},{type:"list",items:["For evening, occasion and travel where bulk matters: pure Pashmina.","For daily winter wear, commuting and hard use: fine merino or Kashmiri handloom wool.","For a first serious piece that will be worn constantly: cashmere sits usefully between the two.","For gifting: Pashmina, almost always — it is the piece people keep."]},{type:"collectionLink",slug:"fine-wool",label:"Browse the Fine Wool collection"}],relatedProductSlugs:["charcoal-fine-wool-shawl","walnut-brown-mens-wool-shawl","ivory-heritage-pashmina-shawl"],relatedCollectionSlugs:["fine-wool","pure-pashmina"]},{slug:"history-of-kashmiri-shawls",title:"A Short History of the Kashmiri Shawl",excerpt:"From the Mughal court to Napoleonic Paris to a Scottish mill town that gave the paisley its English name — how a Srinagar textile became a global object.",category:"indian-textiles",author:"Pashmore Editorial",publishedAt:"2026-04-12",readingMinutes:8,cover:f("history-of-kashmiri-shawls","An antique jamawar shawl showing a repeating buta motif"),blocks:[{type:"paragraph",text:"The Kashmiri shawl is one of the few Indian textiles that changed European fashion rather than the other way round — and one of the few whose imitation abroad became more famous than the original."},{type:"heading",text:"The Mughal century"},{type:"paragraph",text:"Shawl weaving in Kashmir is documented from the fifteenth century, but it was under Mughal patronage that it became an industry. Akbar’s court consumed shawls in quantity and standardised the doshala — shawls given in pairs. Jamawar pieces, patterned across the entire ground, were traded along the routes to Kabul and Isfahan and functioned effectively as currency."},{type:"heading",text:"The buta becomes the paisley"},{type:"paragraph",text:"The teardrop motif that Europe calls paisley is the Kashmiri buta. It arrived in Britain and France around 1800 with shawls carried home by East India Company officers, and demand quickly outran what Srinagar’s looms could supply."},{type:"paragraph",text:"Mills in Norwich, Lyon and — most successfully — Paisley in Renfrewshire began weaving imitations on jacquard looms. The Scottish town produced them in such volume that its name attached itself permanently to a motif that had never been Scottish at all."},{type:"heading",text:"Kani and the talim"},{type:"paragraph",text:"The technique behind the finest of these shawls is kani: instead of a shuttle carrying one weft across the full width, dozens of small wooden bobbins carry short lengths of coloured yarn, building the pattern thread by thread. A weaver works from a talim — a coded pattern script, read aloud in a workshop by a naqash, that records every colour change in every row."},{type:"paragraph",text:"A full-field kani shawl can take two weavers close to two years. It is still made this way in villages around Kanihama, and the talim is still the only way to record the design."},{type:"heading",text:"Collapse and survival"},{type:"paragraph",text:"The Franco-Prussian War of 1870 destroyed the French market almost overnight, and European fashion moved on. Kashmir’s shawl economy contracted brutally; thousands of weavers left the trade. What survived did so through domestic Indian demand — trousseau shawls, occasion pieces, and families who kept the looms because the alternative was losing the skill entirely."},{type:"quote",text:"The talim outlasts the weaver. That is the point of writing it down.",attribution:"A naqash in Kanihama"},{type:"paragraph",text:"Today the Kashmir Pashmina GI registration, introduced in 2008, gives the craft a legal identity for the first time — a way of separating hand-processed Changthangi pashm from everything else sold under the name."},{type:"collectionLink",slug:"kashmiri-collection",label:"Explore the Kashmiri Collection"}],relatedProductSlugs:["paisley-jamawar-womens-shawl","burgundy-kani-weave-pashmina-shawl","antique-gold-jamawar-shawl"],relatedCollectionSlugs:["kashmiri-collection","heritage-collection"]},{slug:"best-shawls-for-wedding-gifting",title:"The Best Shawls for Wedding Gifting",excerpt:"What to give, what to spend, and why ivory outlasts every other choice. A practical guide to gifting handwoven textiles at Indian weddings.",category:"gift-guide",author:"Pashmore Editorial",publishedAt:"2026-04-30",readingMinutes:6,cover:f("best-shawls-for-wedding-gifting","A crimson bridal kani shawl presented in a gift box"),blocks:[{type:"paragraph",text:"A shawl is one of the few wedding presents that is still in use twenty years later. It is also one of the easiest to get wrong, because the obvious choices — bright colours, heavy embroidery — are the ones that date fastest."},{type:"heading",text:"For the bride"},{type:"paragraph",text:"Crimson and deep burgundy are traditional for bridal kani, and a full-field kani shawl is the most significant textile gift that exists in this part of the world. If the budget is not there, an ivory Pashmina with a tilla border does the same job: it reads as ceremonial without competing with the outfit."},{type:"productLink",slug:"crimson-bridal-kani-shawl",label:"Crimson Bridal Kani Shawl"},{type:"heading",text:"For the groom"},{type:"paragraph",text:"A plain charcoal or midnight Pashmina shawl, cut to men’s proportions, worn over a bandhgala. Undecorated is the point — it will be worn at every winter wedding for the rest of his life, which an embroidered piece will not."},{type:"heading",text:"For the families"},{type:"paragraph",text:"Matched sets solve the hardest problem in wedding gifting, which is giving to two people at once without giving them the same thing. A shawl and stole dyed in a single bath read as a pair without being identical."},{type:"heading",text:"What to spend"},{type:"list",items:["Close family: ₹25,000 and above — kani, full sozni, or a numbered piece.","Extended family and close friends: ₹10,000–20,000 — pure Pashmina, tilla border or plain.","Colleagues and wider circle: ₹5,000–10,000 — a boxed Pashmina stole or a fine wool shawl.","Volume gifting: speak to a gifting desk rather than buying retail; most houses box and dispatch individually."]},{type:"heading",text:"Three rules"},{type:"list",items:["Choose ivory or a deep neutral when in doubt. It never dates and it suits everyone.","Insist on presentation — the box, the sleeve and the certificate are half the gift.","Include the craft certificate. Knowing who made it is what turns a purchase into an heirloom."]},{type:"collectionLink",slug:"wedding-gifts",label:"Shop wedding gifts"}],faqs:[{question:"Is it appropriate to gift a shawl at a wedding?",answer:"It is one of the most traditional gifts there is across northern India — shawls have formed part of trousseaus and wedding exchanges for centuries."},{question:"What colour should I avoid?",answer:"Avoid white on its own, which carries mourning associations in several communities. Ivory and cream read as celebratory rather than funereal and are the safest neutral choices."}],relatedProductSlugs:["crimson-bridal-kani-shawl","pure-pashmina-wedding-shawl-ivory-gold","heritage-gift-set-shawl-and-stole"],relatedCollectionSlugs:["wedding-collection","wedding-gifts","gifting"]},{slug:"styling-a-pashmina-shawl",title:"Six Ways to Wear a Pashmina Shawl",excerpt:"The classic drape, the shoulder fold, the double loop and three more — with notes on which cut suits which.",category:"style-guide",author:"Pashmore Editorial",publishedAt:"2026-05-10",readingMinutes:5,cover:f("styling-a-pashmina-shawl","A dusty rose cashmere wrap styled over a linen shirt"),blocks:[{type:"paragraph",text:"A shawl is a rectangle of cloth. Everything interesting about wearing one comes from how you fold it before it goes on."},{type:"subheading",text:"1. The classic drape"},{type:"paragraph",text:"Open, centred across the back, both ends falling in front. Formal, and the only way to show off an embroidered border properly. Needs a full 100 cm width to hang correctly."},{type:"subheading",text:"2. The shoulder fold"},{type:"paragraph",text:"Folded once lengthwise, laid over one shoulder, the tail thrown back. The traditional men’s drape, and the easiest to wear over structured tailoring."},{type:"subheading",text:"3. The double loop"},{type:"paragraph",text:"Folded lengthwise into a band, wrapped twice at the neck with the ends tucked. Best with a narrow stole at 70 cm; a full shawl bulks up too much."},{type:"subheading",text:"4. The belted wrap"},{type:"paragraph",text:"Open over the shoulders like a cape, then belted at the waist over a coat. Turns an oversized wrap into outerwear and works particularly well in double-brushed cashmere."},{type:"subheading",text:"5. The one-shoulder pin"},{type:"paragraph",text:"Gathered at one shoulder and held with a brooch. Occasion dressing; leaves the opposite arm free, which matters more than it sounds at a wedding."},{type:"subheading",text:"6. Simply carried"},{type:"paragraph",text:"Folded in four over the forearm. Not a joke — for warm evenings that turn cold, this is what a light Pashmina is actually for."},{type:"collectionLink",slug:"stoles",label:"Shop stoles"}],relatedProductSlugs:["dusty-rose-cashmere-wrap","soft-cream-ombre-pashmina-wrap","sand-cashmere-stole"],relatedCollectionSlugs:["stoles","womens-shawls"]},{slug:"the-kani-weave-explained",title:"The Kani Weave, Explained",excerpt:"No shuttle, no jacquard, no printing. Dozens of wooden bobbins, a coded script and up to two years on one loom.",category:"kashmiri-craft",author:"Pashmore Editorial",publishedAt:"2026-05-22",readingMinutes:6,cover:f("the-kani-weave-explained","Wooden kani bobbins loaded with coloured yarn on a handloom"),blocks:[{type:"paragraph",text:"Almost every patterned textile you own was printed, or woven on a loom that automates the pattern. Kani does neither. The design is built into the cloth by hand, one short length of weft at a time."},{type:"heading",text:"How it works"},{type:"paragraph",text:"Instead of a shuttle carrying a single weft thread across the full width of the cloth, a kani weaver uses kanis — small eyeless wooden bobbins, each wound with a few metres of one colour. A single row of weft might require forty or fifty of them, each inserted for only the span its colour occupies, then handed on."},{type:"heading",text:"The talim"},{type:"paragraph",text:"The design is not drawn on the loom. It is recorded in a talim: a coded script in which each symbol represents a colour and a number of warp threads. The talim for a full-field shawl can run past four thousand lines. It is read aloud in the workshop, line by line, by a naqash — and it can only be read by someone trained in the notation."},{type:"quote",text:"You do not memorise a talim. You listen to it, for two years.",attribution:"Kani weaver, Kanihama"},{type:"heading",text:"Why it takes so long"},{type:"paragraph",text:"A skilled pair working the same loom in shifts might complete a centimetre of finished cloth in a day. A 220 cm shawl is therefore a project measured in seasons, not weeks. Fewer than a hundred full-field kani shawls are completed in Kashmir in a typical year."},{type:"heading",text:"How to recognise it"},{type:"list",items:["Turn it over: on a true kani the reverse shows the pattern in mirror image, with short floating ends where colours change.","Printed imitations have a flat, uniform reverse.","Embroidered pieces sit on top of the ground cloth; kani is the ground cloth.","Look for slight waviness along colour boundaries — evidence of hand tension."]},{type:"productLink",slug:"burgundy-kani-weave-pashmina-shawl",label:"See a hand-woven kani shawl"}],relatedProductSlugs:["burgundy-kani-weave-pashmina-shawl","crimson-bridal-kani-shawl"],relatedCollectionSlugs:["kashmiri-collection","luxury-collection"]}];function h(){return[...g].sort((a,b)=>new Date(b.publishedAt).getTime()-new Date(a.publishedAt).getTime())}function i(a){return g.find(b=>b.slug===a)??null}function j(a){return h().filter(b=>b.category===a)}function k(a,b=3){return[...h().filter(b=>b.slug!==a.slug&&b.category===a.category),...h().filter(b=>b.slug!==a.slug&&b.category!==a.category)].slice(0,b)}}};